def _install_package() -> None:
    """Unpack the embedded package once and put it on sys.path."""
    digest = _hashlib.sha256(_EMBEDDED_PACKAGE.encode()).hexdigest()[:12]
    target = _os.path.join(_tempfile.gettempdir(), f"aipro_terminal_{digest}")
    marker = _os.path.join(target, ".ready")
    if not _os.path.exists(marker):
        _os.makedirs(target, exist_ok=True)
        _zipfile.ZipFile(_io.BytesIO(_b64.b64decode(_EMBEDDED_PACKAGE))).extractall(target)
        with open(marker, "w", encoding="utf-8") as fh:
            fh.write("ok")
    if target not in _sys.path:
        _sys.path.insert(0, target)


_install_package()

