def render_controls(cfg_in):
    """Auto-refresh, brain and data-source switches.

    These used to sit in a permanent sidebar.  They are settings, not data, so
    they now live inside the ⚙️ Settings tab and the dashboard opens clean.
    """
    st.markdown("### ⚡ टर्मिनल कंट्रोल")
    c1, c2, c3 = st.columns([1.2, 1, 1])
    with c1:
        st.session_state["ui_refresh"] = st.select_slider(
            "Auto refresh (seconds)", options=[15, 30, 60, 120, 300],
            value=int(st.session_state.get("ui_refresh", cfg_in.refresh_seconds)))
    with c2:
        st.session_state["ui_auto"] = st.toggle(
            "Auto refresh ON", value=st.session_state.get("ui_auto", True))
    with c3:
        if st.button("🔄 Refresh now", **container_kw()):
            st.session_state["last_run"] = 0
            st.session_state["global_rows"] = None
            st.rerun()

    st.markdown("### 🧠 AI ब्रेन")
    mode = st.radio("Brain", ["free", "paid"], horizontal=True,
                    index=0 if cfg_in.ai_mode == "free" else 1,
                    help="free = built-in rule engine (कोई key नहीं). "
                         "paid = Gemini/OpenAI LLM से डेस्क नोट + हिंदी कारण.")
    if mode == "paid":
        provs = ["gemini", "openai", "anthropic", "groq", "openrouter"]
        st.session_state["ui_llm_provider"] = st.selectbox(
            "Provider", provs,
            index=provs.index(cfg_in.llm_provider) if cfg_in.llm_provider in provs else 0)
        st.session_state["ui_llm_key"] = st.text_input(
            "API key", value=st.session_state.get("ui_llm_key", cfg_in.llm_api_key),
            type="password")
        st.session_state["ui_llm_model"] = st.text_input(
            "Model", value=st.session_state.get("ui_llm_model", cfg_in.llm_model or "gemini-2.0-flash"))
    else:
        for k in ("ui_llm_provider", "ui_llm_key", "ui_llm_model"):
            st.session_state.pop(k, None)
    cfg_out = build_config()
    st.caption(f"Active brain: **{cfg_out.ai_mode.upper()}**"
               + (f" · {cfg_out.llm_provider}:{cfg_out.llm_model}" if cfg_out.has_paid_ai else "")
               + (" · ✅ secrets.toml से key मिली" if cfg_out.has_paid_ai and not st.session_state.get("ui_llm_key") else ""))

    st.markdown("### 🛰️ डेटा सोर्स")
    d1, d2, d3 = st.columns(3)
    with d1:
        st.session_state["ui_yahoo"] = st.toggle("Yahoo (free, delayed)",
                                                 value=cfg_out.yahoo_enabled)
    with d2:
        st.session_state["ui_nse"] = st.toggle("NSE public JSON", value=cfg_out.nse_enabled)
    with d3:
        st.session_state["ui_news"] = st.toggle("News RSS", value=cfg_out.news_enabled)
    return build_config()




